INSERT IGNORE INTO `wp_yu3posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1114, 1, '2016-08-30 16:30:19', '2016-08-30 07:30:19', '<span style="color: #ff9933;">こんにちは、遊建築工房です。</span><b>\n</b><span style="color: #999999;">\n<span style="color: #000000;">\n<span style="font-size: small;">賃貸アパートの修繕依頼がありました。</span></span></span>\n\n<span style="color: #999999;"><span style="color: #000000;"><span style="font-size: small;">\n内容は、敷地内の駐車ゲートの修繕工事でした。</span></span></span>\n\n<span style="color: #999999;"><span style="color: #000000;"><span style="font-size: small;">\n住人の方が、誤ってぶつけてしまったとかで・・・</span></span></span>\n\n<span style="color: #999999;"><span style="color: #000000;"><span style="font-size: small;">\n自動車保険　適用の案件ということです。</span></span></span>\n\n<span style="color: #999999;"><span style="color: #000000;"><span style="font-size: small;">\n<span style="color: #ff0000;"><b>↓</b></span>元通り、復元</span></span></span>\n\n<span style="color: #999999;"><span style="color: #000000;"><span style="font-size: small;">\n<a id="i13719845042" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e71af9c.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e71af9c.jpg" border="0" alt="" /></a></span></span></span>\n\n<span style="color: #999999;"><span style="color: #000000;"><span style="font-size: small;">\n保険会社様への工事完了の報告も、オーナー様より一任されましたので、</span></span></span><span style="font-size: small; color: #000000;">手配までして終了です。</span>\n\n<span style="color: #999999;"><span style="color: #000000;"><span style="font-size: small;"> クロス張替えやクリーニング・・・など、\nオーナー様に必須の部分リフォームも承っております！\n<span style="color: #ff00cc;"><span style="color: #666666;">\n</span></span></span></span></span>\n<b><span style="color: #660000;">新築、建て替え、リフォーム、オーダーキッチンは</span></b>\n<b><span style="color: #ff6600;">‘遊び心いっぱいの空間づくり’</span></b><span style="color: #660000;"><b>得意とする　遊建築工房へ</b></span><span style="color: #ff0000;"> <b><span style="color: #000000;"><span style="text-decoration: underline;"> </span></span><span style="color: #ff0000;"> </span></b></span>\n\n遊 建築工房\n住所：愛知県名古屋市緑区漆山２０３番地\nフリーダイヤル：0120-799-878\nTEL：052-883-8854\nFAX：052-883-8864(24時間受付)\n営業時間：8：00～19：00\nホームページ：<span style="color: #ff0000;"><a href="http://www.yu-3.jp/">http://www.yu-3.jp</a></span>', 'アパート オーナー様より修繕のご依頼', '', 'inherit', 'open', 'open', '', '1046-autosave-v1', '', '', '2016-08-30 16:30:19', '2016-08-30 07:30:19', '', 1046, 'http://www.yu-3.jp/homes/1046-autosave-v1.html', 0, 'revision', '', 0),
(1880, 24, '2016-11-09 12:28:31', '2016-11-09 03:28:31', '', 'アパート オーナー様より修繕のご依頼', '賃貸アパートの修繕依頼がありました。内容は、敷地内の駐車ゲートの修繕工事でした。保険会社様への工事完了の報告も、オーナー様より一任されましたので、手配までして終了です。クロス張替えやクリーニング・・・など、オーナー様に必須の部分リフォームも承っております！', 'inherit', 'open', 'open', '', '1046-revision-v1', '', '', '2016-11-09 12:28:31', '2016-11-09 03:28:31', '', 1046, 'http://www.yu-3.jp/homes/1046-revision-v1.html', 0, 'revision', '', 0),
