INSERT IGNORE INTO `wp_yu3posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1121, 1, '2016-08-30 16:35:39', '2016-08-30 07:35:39', '<span style="color: #ff9933;">こんにちは、遊建築工房です。</span><b>\n</b><span style="color: #999999;">\n<span style="color: #000000;">\n<span style="font-size: small;">名古屋市緑区の新築現場です。</span></span></span>\n\n<span style="color: #999999;"><span style="color: #000000;"><span style="font-size: small;">\n壁、天井が面になってきました。仕上げの調湿クロスを貼る手前の状態です。\n<a id="i13707198344" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e12a395.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e12a395.jpg" border="0" alt="" /></a>\n大工さんが、\n「１ミリの隙間もなくきっちり仕上げているよ！」と話すので、\n思わず　カメラでズームインしました！\n<a id="i13707199737" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e174e03.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e174e03.jpg" border="0" alt="" /></a>\n丁寧な仕事、ありがとうございます＾＾\nこの時期に、\n<b><span style="color: #ff0000;">↓</span></b>動かさない固定棚の設置と、\n<a id="i13707202246" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e1baab9.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e1baab9.jpg" border="0" alt="" /></a>\n<b><span style="color: #ff0000;">↓</span></b>壁をくり抜いたように仕上がるニッチ棚の加工\n<a id="i13707203290" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e205a15.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e205a15.jpg" border="0" alt="" /></a>\nお客様と綿密な打ち合わせがあって、ここに至っています。\n</span><span style="font-size: small;">\n<b><span style="color: #ff0000;"> </span></b></span></span></span>\n<b><span style="color: #660000;">新築、建て替え、リフォーム、オーダーキッチンは</span></b>\n<b><span style="color: #ff6600;">‘遊び心いっぱいの空間づくり’</span></b><span style="color: #660000;"><b>得意とする　遊建築工房へ</b></span><span style="color: #ff0000;"> <b><span style="color: #000000;"><span style="text-decoration: underline;"> </span></span><span style="color: #ff0000;"> </span></b></span>\n\n遊 建築工房\n住所：愛知県名古屋市緑区漆山２０３番地\nフリーダイヤル：0120-799-878\nTEL：052-883-8854\nFAX：052-883-8864(24時間受付)\n営業時間：8：00～19：00\nホームページ：<span style="color: #ff0000;"><a href="http://www.yu-3.jp/">http://www.yu-3.jp</a></span>', '壁が出来てきました！', '', 'inherit', 'open', 'open', '', '1043-autosave-v1', '', '', '2016-08-30 16:35:39', '2016-08-30 07:35:39', '', 1043, 'http://www.yu-3.jp/homes/1043-autosave-v1.html', 0, 'revision', '', 0),
(1891, 24, '2016-11-09 13:05:39', '2016-11-09 04:05:39', '&nbsp;\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n<b><span style="color: #ff0000"> </span></b></span></span></span>\r\n<b></b>', '名古屋市緑区 注文住宅　 現場日記“壁が出来てきました！”', '名古屋市緑区の新築現場です。お施主様は、いつでも現場へお越しいただけます。見えないところも丁寧に、ウソのない仕事をしている証です。', 'inherit', 'open', 'open', '', '1043-revision-v1', '', '', '2016-11-09 13:05:39', '2016-11-09 04:05:39', '', 1043, 'http://www.yu-3.jp/homes/1043-revision-v1.html', 0, 'revision', '', 0),
(1890, 24, '2016-11-09 12:54:31', '2016-11-09 03:54:31', '<span style="color: #ff9933">こんにちは、遊建築工房です。</span><b>\r\n</b><span style="color: #999999">\r\n<span style="color: #000000">\r\n<span style="font-size: small">名古屋市緑区の新築現場です。</span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n壁、天井が面になってきました。仕上げの調湿クロスを貼る手前の状態です。 </span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n<a id="i13707198344" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e12a395.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e12a395.jpg" border="0" alt="" /></a></span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n大工さんが、「１ミリの隙間もなくきっちり仕上げているよ！」と話すので、思わずカメラでズームインしました！</span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n<a id="i13707199737" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e174e03.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e174e03.jpg" border="0" alt="" /></a></span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n丁寧な仕事、ありがとうございます＾＾</span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\nこの時期に、<b><span style="color: #ff0000">↓</span></b>動かさない固定棚の設置と、</span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n<a id="i13707202246" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e1baab9.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e1baab9.jpg" border="0" alt="" /></a></span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n<b><span style="color: #ff0000">↓</span></b>壁をくり抜いたように仕上がるニッチ棚の加工</span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n<a id="i13707203290" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e205a15.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8e205a15.jpg" border="0" alt="" /></a></span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\nお客様と綿密な打ち合わせがあって、ここに至っています。</span></span></span>\r\n\r\n<span style="color: #999999"><span style="color: #000000"><span style="font-size: small">\r\n<b><span style="color: #ff0000"> </span></b></span></span></span>\r\n<b></b>', '名古屋市緑区 注文住宅　 現場日記“壁が出来てきました！”', '名古屋市緑区の新築現場です。お施主様は、いつでも現場へお越しいただけます。見えないところも丁寧に、ウソのない仕事をしている証です。', 'inherit', 'open', 'open', '', '1043-revision-v1', '', '', '2016-11-09 12:54:31', '2016-11-09 03:54:31', '', 1043, 'http://www.yu-3.jp/homes/1043-revision-v1.html', 0, 'revision', '', 0),
