INSERT IGNORE INTO `wp_yu3posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1170, 1, '2016-08-30 17:05:14', '2016-08-30 08:05:14', '<span style="color: #ff9933;">こんにちは、遊建築工房です。</span><b>\r\n</b><span style="color: #999999;">\r\n<span style="color: #000000;">キッチンリフォームを得意としている弊社ですが、キッチンまるごと入れ替えだけでなく、<b>部材交換も対応</b>できます！</span></span>\r\n\r\n<span style="color: #999999;"><span style="text-decoration: underline;"><b>\r\n</b></span><span style="color: #000000;">予算に合わせてご選択いただければと思います。</span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\n名古屋市天白区にて、換気扇、ガスコンロ、食洗機の交換をしました。</span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;"> <b><span style="color: #ff0000;">\r\n↓交換完了</span></b></span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\n<a id="i13647351441" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8b288654.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8b288654.jpg" border="0" alt="" /></a>\r\n<a id="i13647352479" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8b2e3a5e.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8b2e3a5e.jpg" border="0" alt="" /></a>\r\n<a id="i13647354812" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8b33339b.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8b33339b.jpg" border="0" alt="" /></a></span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\n部材交換なら工期はたった１日で完了します。</span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\n奥様、夕飯の準備に間に合いましたね！</span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\nお客様から、こんな感想を頂戴しました。</span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\n「１３年前の食洗機と比べて、コンパクトなのに容量はアップしています！さらに、音が静かで快適でした！！！」</span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\nキッチン環境のリニューアルで、お料理がますます楽しくなりますね。</span></span>\r\n\r\n&nbsp;\r\n<b><span style="color: #660000;">新築、建て替え、リフォーム、オーダーキッチンは</span></b>\r\n<b><span style="color: #ff6600;">‘遊び心いっぱいの空間づくり’</span></b><span style="color: #660000;"><b>得意とする　遊建築工房へ</b></span>\r\n\r\n遊 建築工房\r\n住所：愛知県名古屋市緑区漆山２０３番地\r\nフリーダイヤル：0120-799-878\r\nTEL：052-883-8854\r\nFAX：052-883-8864(24時間受付)\r\n営業時間：8：00～19：00\r\nホームページ：<span style="color: #ff0000;"><a href="http://www.yu-3.jp/">http://www.yu-3.jp/</a></span>', 'キッチン部材交換　換気扇・ガスコンロ・食洗機', 'キッチンリフォームを得意としている弊社ですが、\r\nキッチンまるごと入れ替えだけでなく、\r\n部材交換も対応できます！\r\n予算に合わせてご選択いただければと思います。\r\n名古屋市天白区にて、\r\n換気扇、ガスコンロ、食洗機の交換をしました。', 'inherit', 'open', 'open', '', '1019-revision-v1', '', '', '2016-08-30 17:05:14', '2016-08-30 08:05:14', '', 1019, 'http://www.yu-3.jp/homes/1019-revision-v1.html', 0, 'revision', '', 0),
(1171, 1, '2016-12-07 10:48:27', '2016-12-07 01:48:27', '', 'テラス設置　ガーデニングにティータイムに＾＾', '「テラス設置工事」完了しました！こちらのテラスは、オーダーです。オーダーにしたのには、ちゃんと理由があります。奥様チョイスのペンダントライトを設置して、完成！！', 'inherit', 'open', 'open', '', '1018-autosave-v1', '', '', '2016-12-07 10:48:27', '2016-12-07 01:48:27', '', 1018, 'http://www.yu-3.jp/homes/1018-autosave-v1.html', 0, 'revision', '', 0),
